#!/usr/bin/env python3
"""Check only this project's sources, using pinned, already-built dependencies."""
from pathlib import Path
import argparse
import datetime
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys

ROOT = Path(__file__).resolve().parent
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--packages-dir', type=Path, default=ROOT / '.lake/packages')
parser.add_argument('sources', nargs='*', help='Relative .lean sources; default checks all in order.')
args = parser.parse_args()
packages = args.packages_dir.resolve()
manifest = json.loads((ROOT / 'lake-manifest.json').read_text())
for package in manifest['packages']:
    checkout = packages / package['name']
    actual = subprocess.check_output(
        ['git', '-C', str(checkout), 'rev-parse', 'HEAD'], text=True).strip()
    if actual != package['rev']:
        sys.exit(f"Dependency revision mismatch for {package['name']}: {actual}")

lean = shutil.which('lean')
if lean is None:
    sys.exit('lean is not on PATH; install the pinned toolchain with elan first.')
version = subprocess.check_output([lean, '--version'], cwd=ROOT, text=True).strip()
if 'version 4.33.0' not in version:
    sys.exit(f'Wrong Lean version: {version}')

paths = [ROOT] + sorted(p / '.lake/build/lib/lean' for p in packages.iterdir()
                        if (p / '.lake/build/lib/lean').is_dir())
env = os.environ.copy()
env['LEAN_PATH'] = os.pathsep.join(map(str, paths))
